-- 018_diversify_ebm_short_descriptions.sql
-- Diversifica el short_description de los 106 centros "Escola Bressol
-- Municipal" (source_group=ebm_municipal) de Barcelona. Hasta ahora los 106
-- compartian literalmente el mismo texto salvo nombre y distrito -- una
-- plantilla de sustitucion de variables detectada en la auditoria SEO como
-- riesgo de contenido duplicado a nivel de tarjeta/listado (el short_
-- description se muestra en CenterCard dentro de las landings de tipo).
--
-- Cada nuevo texto usa una de 8 estructuras de frase distintas, rotadas por
-- orden, construidas UNICAMENTE con datos ya presentes en la ficha de cada
-- centro (nombre, direccion, distrito, horario, servicios) -- no se ha
-- inventado ningun dato nuevo. El horario y los servicios (comedor, cocina
-- propia) son identicos en los 106 centros porque es el mismo sistema
-- municipal real (IMEB), asi que se mantienen sin alterar; lo que cambia es
-- la redaccion.
--
-- No toca long_description, faqs, ni ningun otro campo. No toca Madrid ni
-- ningun centro fuera de ebm_municipal.
--
-- Generado: 2026-07-10. Revisar antes de ejecutar.
-- Sin DELETE / DROP / TRUNCATE.

BEGIN;

UPDATE centers SET short_description = 'Escola Bressol Municipal Aurora es una escuela infantil de titularidad pública situada en Aurora, 24, en el distrito de Ciutat Vella, Barcelona. Forma parte de la red de Escoles Bressol Municipals gestionada por el Institut Municipal d''Educació de Barcelona (IMEB) y atiende el primer ciclo de educación infantil, de 0 a 3 años. El centro dispone de cocina propia para el servicio de comedor y abre de lunes a viernes de 8:00 a 17:00 h (8:00 a 15:00 en septiembre y julio). El acceso se gestiona mediante el proceso de preinscripción municipal.', updated_at = NOW() WHERE slug = 'escola-bressol-municipal-aurora-barcelona';
